use super::*;

/// Test that BVar with out-of-scope index triggers UnboundVariable error
#[test]
fn test_error_unbound_variable() {
    let env = Environment::new();
    let tc = TypeChecker::new(&env);

    // BVar(0) in empty context - no binders to reference
    let unbound = Expr::bvar(0);
    let result = tc.infer_type(&unbound);
    assert!(
        matches!(result, Err(TypeError::UnboundVariable(0))),
        "Expected UnboundVariable(0), got {result:?}"
    );

    // BVar(5) in empty context
    let unbound5 = Expr::bvar(5);
    let result = tc.infer_type(&unbound5);
    assert!(
        matches!(result, Err(TypeError::UnboundVariable(5))),
        "Expected UnboundVariable(5), got {result:?}"
    );

    // BVar(1) inside a lambda only has 1 binder (index 0)
    // λ (x : Prop). BVar(1)  -- should fail
    // Note: The error reports the shifted index (0 = 1-1 after one binder)
    let bad_lam = Expr::lam(BinderInfo::Default, Expr::prop(), Expr::bvar(1));
    let result = tc.infer_type(&bad_lam);
    assert!(
        matches!(result, Err(TypeError::UnboundVariable(0))),
        "Expected UnboundVariable(0), got {result:?}"
    );
}

