/// Test that application to non-function type triggers NotAFunction error
#[test]
fn test_error_not_a_function() {
    let env = Environment::new();
    let tc = TypeChecker::new(&env);

    // Apply Prop to Prop - Prop is not a function type
    let bad_app = Expr::app(Expr::prop(), Expr::prop());
    let result = tc.infer_type(&bad_app);
    assert!(
        matches!(result, Err(TypeError::NotAFunction { .. })),
        "Expected NotAFunction, got {result:?}"
    );

    // Apply Sort to Sort
    let bad_app2 = Expr::app(Expr::type_(), Expr::prop());
    let result = tc.infer_type(&bad_app2);
    assert!(
        matches!(result, Err(TypeError::NotAFunction { .. })),
        "Expected NotAFunction, got {result:?}"
    );

    // Apply literal to literal - 42 is not a function
    let bad_app3 = Expr::app(Expr::nat_lit(42), Expr::nat_lit(1));
    let result = tc.infer_type(&bad_app3);
    assert!(
        matches!(result, Err(TypeError::NotAFunction { .. })),
        "Expected NotAFunction, got {result:?}"
    );
}

/// Test that expected sort in type position triggers ExpectedSort error
#[test]
fn test_error_expected_sort() {
    let env = Environment::new();
    let tc = TypeChecker::new(&env);

    // Pi with non-sort as domain type: (x : 42) → Prop
    // 42 : Nat, Nat is not a Sort
    let bad_pi = Expr::pi(BinderInfo::Default, Expr::nat_lit(42), Expr::prop());
    let result = tc.infer_type(&bad_pi);
    assert!(
        matches!(result, Err(TypeError::ExpectedSort { .. })),
        "Expected ExpectedSort, got {result:?}"
    );

    // Lambda with non-sort as binder type: λ (x : 1). x
    // Lean 4 parity: infer_type uses infer_only=true and skips the domain
    // Sort check for lambdas (Part of #3223). Only check_type catches this.
    let bad_lam = Expr::lam(BinderInfo::Default, Expr::nat_lit(1), Expr::bvar(0));
    let result = tc.infer_type(&bad_lam);
    assert!(
        result.is_ok(),
        "infer_type with infer_only=true should skip lambda domain Sort check, got {result:?}"
    );

    // But check_type (infer_only=false) should still catch it
    let result = tc.check_type(&bad_lam, &Expr::prop());
    assert!(
        matches!(result, Err(TypeError::ExpectedSort { .. })),
        "check_type should catch lambda domain Sort error, got {result:?}"
    );
}

