/// Test that projection on unknown inductive type triggers UnknownConst error.
///
/// After #2208 changed `is_prop` to return `Result<bool, TypeError>` (propagating
/// errors via `?`), the `is_prop` call in `infer_proj_type_from_impl` fires before
/// the `get_inductive` lookup. Since the const doesn't exist in the environment at
/// all, `infer_type(Const("NonExistent.Struct"))` fails with `UnknownConst` inside
/// `is_prop`, and that error propagates out before the projection-specific
/// `UnknownInductive` check is reached.
#[test]
fn test_error_unknown_inductive() {
    let env = Environment::new();
    let tc = TypeChecker::new(&env);

    // Create a value whose type is a Const pointing to unknown inductive
    // Use an FVar with a fake type that is a Const for a non-existent inductive
    let unknown_ind = Name::from_string("NonExistent.Struct");
    let fake_type = Expr::const_(unknown_ind.clone(), vec![]);

    // Push an FVar with this fake type into the local context
    let fvar_id = tc
        .ctx
        .borrow_mut()
        .push(Name::from_string("x"), fake_type, BinderInfo::Default);

    let fvar = Expr::fvar(fvar_id);
    let proj = Expr::proj(unknown_ind.clone(), 0, fvar);
    let result = tc.infer_type(&proj);

    // Since #2208, is_prop propagates errors: infer_type on the unknown const
    // fails with UnknownConst before get_inductive can produce UnknownInductive.
    assert!(
        matches!(result, Err(TypeError::UnknownConst(ref name)) if *name == unknown_ind),
        "Expected UnknownConst for {unknown_ind}, got {result:?}"
    );
}

/// Test that projection with out-of-bounds index triggers InvalidProjIndexOutOfBounds error
#[test]
fn test_error_proj_index_out_of_bounds() {
    use crate::inductive::{Constructor, InductiveDecl, InductiveType};

    let mut env = Environment::new();

    // First add Nat to the environment (needed for field types)
    let nat_name = Name::from_string("Nat");
    let nat_decl = InductiveDecl {
        level_params: vec![],
        num_params: 0,
        types: vec![InductiveType {
            name: nat_name.clone(),
            type_: Expr::type_(),
            constructors: vec![
                Constructor {
                    name: Name::from_string("Nat.zero"),
                    type_: Expr::const_(nat_name.clone(), vec![]),
                },
                Constructor {
                    name: Name::from_string("Nat.succ"),
                    type_: Expr::pi(
                        BinderInfo::Default,
                        Expr::const_(nat_name.clone(), vec![]),
                        Expr::const_(nat_name.clone(), vec![]),
                    ),
                },
            ],
        }],
    };
    env.add_inductive(nat_decl).unwrap();

    // Define SingleField : Type with mk : Nat → SingleField (1 field)
    let sf_name = Name::from_string("SingleField");
    let nat_ty = Expr::const_(nat_name.clone(), vec![]);

    let sf_mk_type = Expr::pi(
        BinderInfo::Default,
        nat_ty.clone(), // val : Nat
        Expr::const_(sf_name.clone(), vec![]),
    );

    let sf_decl = InductiveDecl {
        level_params: vec![],
        num_params: 0,
        types: vec![InductiveType {
            name: sf_name.clone(),
            type_: Expr::type_(),
            constructors: vec![Constructor {
                name: Name::from_string("SingleField.mk"),
                type_: sf_mk_type,
            }],
        }],
    };
    env.add_inductive(sf_decl).unwrap();

    let tc = TypeChecker::new(&env);

    // Create SingleField.mk 42
    let mk = Expr::const_(Name::from_string("SingleField.mk"), vec![]);
    let sf_val = Expr::app(mk, Expr::nat_lit(42));

    // Project field 0 — should yield Nat (the single field's type)
    let proj0_ty = tc
        .infer_type(&Expr::proj(sf_name.clone(), 0, sf_val.clone()))
        .expect("Proj index 0 should succeed");
    assert_eq!(
        proj0_ty, nat_ty,
        "Proj(SingleField, 0) should have type Nat"
    );

    // Out-of-bounds indices should fail with InvalidProjIndexOutOfBounds
    for idx in [1u32, 100, u32::MAX] {
        let proj = Expr::proj(sf_name.clone(), idx, sf_val.clone());
        let result = tc.infer_type(&proj);
        assert!(
            matches!(result, Err(TypeError::InvalidProjIndexOutOfBounds(i, 1)) if i == idx),
            "Expected InvalidProjIndexOutOfBounds({idx}, 1), got {result:?}"
        );
    }
}

/// Test type mismatch in application arguments.
///
/// Lean 4 parity: `infer_type` passes `infer_only=true` and skips App
/// argument type checking. `check_type` passes `infer_only=false` and
/// catches mismatches. Ref: type_checker.cpp:163-196, 304-311.
#[test]
fn test_error_type_mismatch() {
    use crate::env::Declaration;

    let mut env = Environment::new();

    // Add a function that expects Prop
    let fn_type = Expr::pi(BinderInfo::Default, Expr::prop(), Expr::prop());
    let fn_value = Expr::lam(BinderInfo::Default, Expr::prop(), Expr::bvar(0));
    env.add_decl(Declaration::Definition {
        name: Name::from_string("takeProp"),
        level_params: vec![],
        type_: fn_type.clone(),
        value: fn_value,
        is_reducible: true,
    })
    .unwrap();

    let tc = TypeChecker::new(&env);

    // Apply takeProp to a Nat literal instead of Prop
    let fn_ref = Expr::const_(Name::from_string("takeProp"), vec![]);
    let bad_app = Expr::app(fn_ref, Expr::nat_lit(42));

    // Lean 4 parity: infer_type succeeds (skips App arg check)
    let inferred = tc
        .infer_type(&bad_app)
        .expect("infer_type should succeed in infer_only mode (Lean 4 parity)");
    // The result type is Prop (the codomain of takeProp : Prop -> Prop)
    assert!(
        inferred.is_prop(),
        "infer_type should return the codomain type, got {inferred:?}"
    );

    // check_type catches the mismatch (infer_only=false, full checking)
    let result = tc.check_type(&bad_app, &Expr::prop());
    assert!(
        matches!(result, Err(TypeError::TypeMismatch { .. })),
        "check_type should catch TypeMismatch, got {result:?}"
    );
}

