/// Test that projection from Prop type with non-Prop field triggers InvalidProjFromProp error.
///
/// Per Lean 4 (type_checker.cpp:260-262), projections from Prop types must only
/// yield Prop-typed fields to preserve proof irrelevance.
#[test]
fn test_error_invalid_proj_from_prop() {
    use crate::inductive::{Constructor, InductiveDecl, InductiveType};

    let mut env = Environment::new();

    // First add Nat to the environment (needed for the non-Prop field type)
    let nat_name = Name::from_string("Nat");
    let nat_decl = InductiveDecl {
        level_params: vec![],
        num_params: 0,
        types: vec![InductiveType {
            name: nat_name.clone(),
            type_: Expr::type_(),
            constructors: vec![
                Constructor {
                    name: Name::from_string("Nat.zero"),
                    type_: Expr::const_(nat_name.clone(), vec![]),
                },
                Constructor {
                    name: Name::from_string("Nat.succ"),
                    type_: Expr::pi(
                        BinderInfo::Default,
                        Expr::const_(nat_name.clone(), vec![]),
                        Expr::const_(nat_name.clone(), vec![]),
                    ),
                },
            ],
        }],
    };
    env.add_inductive(nat_decl).unwrap();

    // Create a structure in Prop with a non-Prop field.
    // This is an ill-formed structure that violates proof irrelevance,
    // but we construct it manually to test the validation.
    //
    // PropWithData : Prop
    // PropWithData.mk : Nat → PropWithData
    //
    // The field has type Nat : Type, which is NOT in Prop.
    let pwd_name = Name::from_string("PropWithData");
    let nat_ty = Expr::const_(nat_name.clone(), vec![]);

    let pwd_mk_type = Expr::pi(
        BinderInfo::Default,
        nat_ty.clone(), // data : Nat (NOT in Prop!)
        Expr::const_(pwd_name.clone(), vec![]),
    );

    let pwd_decl = InductiveDecl {
        level_params: vec![],
        num_params: 0,
        types: vec![InductiveType {
            name: pwd_name.clone(),
            type_: Expr::prop(), // Key: type is Prop, not Type
            constructors: vec![Constructor {
                name: Name::from_string("PropWithData.mk"),
                type_: pwd_mk_type,
            }],
        }],
    };
    env.add_inductive(pwd_decl).unwrap();

    let tc = TypeChecker::new(&env);

    // Create a value: PropWithData.mk 42
    let mk = Expr::const_(Name::from_string("PropWithData.mk"), vec![]);
    let pwd_val = Expr::app(mk, Expr::nat_lit(42));

    // Try to project field 0 (the Nat field from a Prop-typed structure)
    // This MUST fail because projecting a non-Prop field from a Prop type
    // would violate proof irrelevance.
    let proj = Expr::proj(pwd_name.clone(), 0, pwd_val);
    let result = tc.infer_type(&proj);

    assert!(
        matches!(result, Err(TypeError::InvalidProjFromProp { field_idx: 0 })),
        "Expected InvalidProjFromProp {{ field_idx: 0 }}, got {result:?}"
    );
}

/// Regression for #1516: quick projection inference must not populate cache
/// entries that let strict projection typing bypass Prop validation.
#[test]
fn test_error_invalid_proj_from_prop_after_quick_projection_inference() {
    use crate::inductive::{Constructor, InductiveDecl, InductiveType};

    let mut env = Environment::new();
    env.init_nat().unwrap();

    // PropWithDataQuick : Prop
    // PropWithDataQuick.mk : Nat → PropWithDataQuick
    let pwd_name = Name::from_string("PropWithDataQuick");
    let nat_ty = Expr::const_(Name::from_string("Nat"), vec![]);
    let mk_type = Expr::pi(
        BinderInfo::Default,
        nat_ty.clone(),
        Expr::const_(pwd_name.clone(), vec![]),
    );

    env.add_inductive(InductiveDecl {
        level_params: vec![],
        num_params: 0,
        types: vec![InductiveType {
            name: pwd_name.clone(),
            type_: Expr::prop(),
            constructors: vec![Constructor {
                name: Name::from_string("PropWithDataQuick.mk"),
                type_: mk_type,
            }],
        }],
    })
    .unwrap();

    let tc = TypeChecker::new(&env);

    let mk = Expr::const_(Name::from_string("PropWithDataQuick.mk"), vec![]);
    let val = Expr::app(mk, Expr::nat_lit(7));
    let proj = Expr::proj(pwd_name, 0, val);

    // Prime quick projection typing first (this is where cache pollution occurred).
    let quick_ty = tc.try_infer_type_quick(&proj);
    assert_eq!(
        quick_ty,
        Some(nat_ty),
        "quick projection inference should still infer Nat for the field"
    );

    // Strict infer_type must still reject projection from Prop to non-Prop.
    let result = tc.infer_type(&proj);
    assert!(
        matches!(result, Err(TypeError::InvalidProjFromProp { field_idx: 0 })),
        "Expected InvalidProjFromProp {{ field_idx: 0 }} after quick-path inference, got {result:?}"
    );
}

/// Regression: projection traversal must reject dependent substitutions
/// from non-Prop fields when the structure type is Prop.
///
/// Lean 4 checks this in the pre-target field traversal (type_checker.cpp:253).
#[test]
fn test_error_invalid_dependent_proj_from_prop() {
    use crate::env::Declaration;
    use crate::inductive::{Constructor, InductiveDecl, InductiveType};

    let mut env = Environment::new();
    env.init_nat().unwrap();
    env.init_eq().unwrap();

    // PropDep : Prop
    // PropDep.mk : (n : Nat) -> Eq Nat n n -> PropDep
    //
    // Field 1 depends on field 0, so projecting field 1 requires substituting
    // projection 0. Since field 0 is Nat (not Prop) and PropDep : Prop,
    // this must be rejected.
    let prop_dep_name = Name::from_string("PropDep");
    let nat_ty = Expr::const_(Name::from_string("Nat"), vec![]);
    let eq_const = Expr::const_(Name::from_string("Eq"), vec![Level::succ(Level::zero())]);
    let dep_eq_ty = Expr::app(
        Expr::app(Expr::app(eq_const, nat_ty.clone()), Expr::bvar(0)),
        Expr::bvar(0),
    );
    let mk_type = Expr::pi(
        BinderInfo::Default,
        nat_ty.clone(),
        Expr::pi(
            BinderInfo::Default,
            dep_eq_ty,
            Expr::const_(prop_dep_name.clone(), vec![]),
        ),
    );

    env.add_inductive(InductiveDecl {
        level_params: vec![],
        num_params: 0,
        types: vec![InductiveType {
            name: prop_dep_name.clone(),
            type_: Expr::prop(),
            constructors: vec![Constructor {
                name: Name::from_string("PropDep.mk"),
                type_: mk_type,
            }],
        }],
    })
    .unwrap();

    // h : Eq Nat 42 42
    let eq_nat_42 = Expr::app(
        Expr::app(
            Expr::app(
                Expr::const_(Name::from_string("Eq"), vec![Level::succ(Level::zero())]),
                nat_ty,
            ),
            Expr::nat_lit(42),
        ),
        Expr::nat_lit(42),
    );
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("h"),
        level_params: vec![],
        type_: eq_nat_42,
    })
    .unwrap();

    let tc = TypeChecker::new(&env);
    let mk = Expr::const_(Name::from_string("PropDep.mk"), vec![]);
    let h = Expr::const_(Name::from_string("h"), vec![]);
    let prop_dep_val = Expr::app(Expr::app(mk, Expr::nat_lit(42)), h);

    // Project dependent field 1 (Eq Nat n n). This should fail before reaching
    // the target field domain because traversal must substitute field 0 (Nat).
    let proj = Expr::proj(prop_dep_name, 1, prop_dep_val);
    let result = tc.infer_type(&proj);

    assert!(
        matches!(result, Err(TypeError::InvalidProjFromProp { field_idx: 0 })),
        "Expected InvalidProjFromProp {{ field_idx: 0 }}, got {result:?}"
    );
}

