/// Test that NotAFunction error carries the correct struct variant.
///
/// Constructs `App(Sort(0), Sort(0))` — applying Prop (a Sort) as if it were
/// a function. The error should use the new struct variant with ty and location.
#[test]
fn test_location_not_a_function_struct_variant() {
    let env = Environment::new();
    let tc = TypeChecker::new(&env);

    // App(Prop, Prop) — Prop is Sort(0), not a function type
    let bad = Expr::app(Expr::prop(), Expr::prop());
    let result = tc.infer_type(&bad);
    assert!(
        matches!(result, Err(TypeError::NotAFunction { .. })),
        "Expected NotAFunction, got {result:?}"
    );
    if let Err(TypeError::NotAFunction { ty, location }) = result {
        // ty should be the type of Prop (which is Type/Sort(1))
        assert!(
            matches!(ty.kind(), ExprKind::Sort(_)),
            "Expected Sort type, got {:?}",
            ty
        );
        let _ = location; // field exists
    }
}

/// Test that TypeMismatch carries location when triggered via check_type.
#[test]
fn test_location_type_mismatch_via_check_type() {
    let env = Environment::new();
    let tc = TypeChecker::new(&env);

    // Sort(1) : Sort(2), but we expect Sort(0)
    let sort1 = Expr::sort(Level::succ(Level::zero()));
    let sort0 = Expr::sort(Level::zero());
    let result = tc.check_type(&sort1, &sort0);
    if let Err(TypeError::TypeMismatch { location, .. }) = result {
        // Location field should exist (may be None at top level)
        let _ = location;
    }
}

/// Test that set_expr_loc_decl_name includes the declaration name in errors.
#[test]
fn test_location_decl_name_in_error() {
    let env = Environment::new();
    let tc = TypeChecker::new(&env);

    // Set a declaration name
    tc.set_expr_loc_decl_name(Name::from_string("MyDecl"));

    // Trigger a NotAFunction error
    let bad = Expr::app(Expr::prop(), Expr::prop());
    let result = tc.infer_type(&bad);

    if let Err(err) = &result {
        if let Some(loc) = err.location() {
            assert_eq!(
                loc.decl_name.as_ref().map(|n| n.to_string()),
                Some("MyDecl".to_string())
            );
            assert!(loc.to_string().contains("MyDecl"));
        }
    }
}

/// Test that with_location method works on TypeError.
#[test]
fn test_with_location_method() {
    use crate::tc::expr_location::{ExprLocation, ExprPathStep};

    let err = TypeError::TypeMismatch {
        expected: Box::new(Expr::prop()),
        inferred: Box::new(Expr::type_()),
        location: None,
    };

    // Should have no location initially
    assert!(err.location().is_none());

    // Attach a location
    let mut loc = ExprLocation::with_decl_name(Name::from_string("test.decl"));
    loc.push(ExprPathStep::AppArg);
    let err = err.with_location(Some(Box::new(loc)));

    // Now should have location
    let loc = err
        .location()
        .expect("should have location after with_location");
    assert_eq!(
        loc.decl_name.as_ref().map(|n| n.to_string()),
        Some("test.decl".to_string())
    );
    assert_eq!(loc.steps.len(), 1);
    assert_eq!(loc.steps[0], ExprPathStep::AppArg);
}

/// Test that location is included in error Display output.
#[test]
fn test_location_in_display_output() {
    use crate::tc::expr_location::{ExprLocation, ExprPathStep};

    let mut loc = ExprLocation::with_decl_name(Name::from_string("Nat.add"));
    loc.push(ExprPathStep::AppArg);
    loc.push(ExprPathStep::LamBody);

    let err = TypeError::TypeMismatch {
        expected: Box::new(Expr::prop()),
        inferred: Box::new(Expr::type_()),
        location: Some(Box::new(loc)),
    };

    let msg = err.to_string();
    assert!(
        msg.contains("Nat.add"),
        "Error message should contain declaration name, got: {msg}"
    );
    assert!(
        msg.contains("argument of application"),
        "Error message should contain path step, got: {msg}"
    );
    assert!(
        msg.contains("body of lambda"),
        "Error message should contain path step, got: {msg}"
    );
}

/// Test that NotAFunction error display includes location.
#[test]
fn test_not_a_function_display_with_location() {
    use crate::tc::expr_location::{ExprLocation, ExprPathStep};

    let mut loc = ExprLocation::new();
    loc.push(ExprPathStep::AppFn);

    let err = TypeError::NotAFunction {
        ty: Box::new(Expr::prop()),
        location: Some(Box::new(loc)),
    };

    let msg = err.to_string();
    assert!(
        msg.contains("function of application"),
        "NotAFunction display should include location, got: {msg}"
    );
}

/// Test that ExpectedSort error display includes location.
#[test]
fn test_expected_sort_display_with_location() {
    use crate::tc::expr_location::{ExprLocation, ExprPathStep};

    let mut loc = ExprLocation::with_decl_name(Name::from_string("bad.pi"));
    loc.push(ExprPathStep::PiDom);

    let err = TypeError::ExpectedSort {
        ty: Box::new(Expr::prop()),
        location: Some(Box::new(loc)),
    };

    let msg = err.to_string();
    assert!(
        msg.contains("bad.pi"),
        "ExpectedSort display should include decl name, got: {msg}"
    );
    assert!(
        msg.contains("domain of Pi"),
        "ExpectedSort display should include location step, got: {msg}"
    );
}

/// Test that errors without location still display correctly (backward compatible).
#[test]
fn test_error_display_without_location() {
    let err = TypeError::TypeMismatch {
        expected: Box::new(Expr::prop()),
        inferred: Box::new(Expr::type_()),
        location: None,
    };
    let msg = err.to_string();
    assert!(
        msg.contains("Type mismatch"),
        "Should display normal error message, got: {msg}"
    );
    // Should NOT contain newline from location formatting
    assert!(
        !msg.contains("\n  in declaration"),
        "Should not have location suffix, got: {msg}"
    );
}
